{"cmd":"python3 - <<'PY'
import json
import re
import zipfile
from docx import Document

TEMPLATE = '/root/offer_letter_template.docx'
DATA = '/root/employee_data.json'
OUTPUT = '/root/offer_letter_filled.docx'

with open(DATA, 'r', encoding='utf-8') as f:
    data = json.load(f)

mapping = {f'{{{{{k}}}}}': str(v) for k, v in data.items()}
keep_relocation = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

BLOCK_RE = re.compile(r"\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}", re.DOTALL)
PLACEHOLDER_RE = re.compile(r"\{\{[^}]+\}\}")


def iter_paragraphs_in_container(container):
    for p in container.paragraphs:
        yield p
    for t in container.tables:
        yield from iter_paragraphs_in_table(t)


def iter_paragraphs_in_table(table):
    for row in table.rows:
        for cell in row.cells:
            yield from iter_paragraphs_in_container(cell)


def get_run_starts(texts):
    starts = []
    pos = 0
    for t in texts:
        starts.append(pos)
        pos += len(t)
    return starts


def run_index_for(pos, run_starts):
    idx = 0
    for i, s in enumerate(run_starts):
        if s <= pos:
            idx = i
        else:
            break
    return idx


def replace_span_in_runs(runs, run_starts, start, end, replacement):
    if start >= end:
        return
    start_run = run_index_for(start, run_starts)
    end_run = run_index_for(end - 1, run_starts)

    sr_text = runs[start_run].text
    sr_off = start - run_starts[start_run]

    if start_run == end_run:
        er_off = end - run_starts[end_run]
        runs[start_run].text = sr_text[:sr_off] + replacement + sr_text[er_off:]
    else:
        runs[start_run].text = sr_text[:sr_off] + replacement
        for ri in range(start_run + 1, end_run):
            runs[ri].text = ""
        er_text = runs[end_run].text
        er_off = end - run_starts[end_run]
        runs[end_run].text = er_text[er_off:]


def process_paragraph(paragraph):
    runs = paragraph.runs
    if not runs:
        return

    # Pass 1: conditional block
    texts = [r.text for r in runs]
    full = "".join(texts)
    if "{{IF_RELOCATION}}" in full:
        run_starts = get_run_starts(texts)
        matches = list(BLOCK_RE.finditer(full))
        for m in reversed(matches):
            replacement = m.group(1) if keep_relocation else ""
            replace_span_in_runs(runs, run_starts, m.start(), m.end(), replacement)

    # Pass 2: placeholders
    texts = [r.text for r in runs]
    full = "".join(texts)
    run_starts = get_run_starts(texts)
    matches = list(PLACEHOLDER_RE.finditer(full))
    for m in reversed(matches):
        token = m.group(0)
        replacement = mapping.get(token, token)
        replace_span_in_runs(runs, run_starts, m.start(), m.end(), replacement)


doc = Document(TEMPLATE)

for p in iter_paragraphs_in_container(doc):
    process_paragraph(p)

for section in doc.sections:
    for p in iter_paragraphs_in_container(section.header):
        process_paragraph(p)
    for p in iter_paragraphs_in_container(section.footer):
        process_paragraph(p)

doc.save(OUTPUT)

# Basic verification: ensure no placeholders remain
with zipfile.ZipFile(OUTPUT) as z:
    xml_files = [n for n in z.namelist() if n.startswith('word/') and n.endswith('.xml')]
    leftovers = []
    for n in xml_files:
        data = z.read(n).decode('utf-8')
        if '{{' in data:
            leftovers.append(n)
    print('leftover placeholders in:', leftovers)
PY"}
